	int	your_ref;	/* Offset 12	*/
	bits	action;		/* Offset 16	*/
	byte	reserved[236];	/* Offset 20	*/
};

struct wimp_message_list {
	int messages[UNKNOWN];
};

typedef struct wimp_message_list wimp_message_list;

extern os_error *xwimp_add_messages(
	wimp_message_list const *messages
);

extern os_error *xwimp_remove_messages(
	wimp_message_list const *messages
